            if (!in_range(ptr, layout::dungeon::kDisplayDataOffset + layout::display_data::kSize)) {
                return 0u;
            }
        }
        return ptr;
    }

private:
    const uint8_t* main_ram_ = nullptr;
    size_t size_ = 0;
};

