/// Writes a trivially copyable value into simulated guest Main RAM with bounds checking.
template <typename T>
void WriteGuest(std::vector<uint8_t>& ram, uint32_t guest_addr, T value) {
    assert(guest_addr >= layout::kMainRamBase);
