        patch = repo / 'patches' / f'ndsrecomp-{name}.patch'
        subprocess.run(['git', 'apply', str(patch)], cwd=root, check=True)
    for name in patches:
        patch = repo / 'patches' / f'ndsrecomp-{name}.patch'
        subprocess.run(['git', 'apply', '--reverse', '--check', str(patch)], cwd=root, check=True)
print('Clean patch application and cached-setup checks passed for the desktop and iOS patch stack.')
